        if((*env)->ExceptionOccurred(env))
            return 0;

        JDOUBLE_ARRAY_TYPE = (*env)->NewGlobalRef(env, clazz);
        (*env)->DeleteLocalRef(env, clazz);
    }
#endif

    return 1;
}


